<script>
 import {onMount} from 'svelte';import {listDeployments,listSites,sendCommand} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';
 let deployments=[],sites=[],loading=true,busy=false,selected='';
 async function load(){const [d,s]=await Promise.all([listDeployments(),listSites()]);if(d.ok)deployments=d.data.deployments||[];else notify(d.error||'Не удалось загрузить историю','error');if(s.ok)sites=s.data.sites||[];loading=false}
 onMount(load);
 async function pull(){if(!selected)return;const [deviceId,siteId]=selected.split(':');busy=true;const r=await sendCommand(Number(deviceId),'git_pull',{site_id:siteId});busy=false;if(r.ok&&r.data.ok){notify(r.data.message||'Git pull выполнен','success');await load()}else notify(r.data?.message||r.error||'Git pull failed','error')}
 function label(action){return ({create_site:'Site created',start_site:'Site started',stop_site:'Site stopped',git_pull:'Git pull'})[action]||action}
</script>
<div class="page-header"><div><div class="eyebrow">DELIVERY</div><h1 class="page-title">Deployments</h1><p class="page-desc">История операций с сайтами и ручной Git Pull.</p></div><Button on:click={load}>↻ Обновить</Button></div>
<section class="deploy-action"><div><strong>Update from Git</strong><small>Выполняет git pull --ff-only в каталоге выбранного сайта.</small></div><div class="action-controls"><select class="input" bind:value={selected}><option value="">Выбрать сайт</option>{#each sites as item}<option value={item.device_id+':'+item.site.site_id}>{item.device_name} / {item.site.site_id}</option>{/each}</select><Button variant="primary" disabled={!selected||busy} loading={busy} on:click={pull}>Git Pull</Button></div></section>
{#if loading}<div class="empty">Загрузка истории…</div>{:else if !deployments.length}<div class="empty">Операций пока нет. Создание сайта, запуск и Git Pull появятся здесь.</div>{:else}<div class="history">{#each deployments as d}<article class="history-row"><span class="history-icon">⇧</span><div class="history-copy"><strong>{label(d.action)}</strong><small>{d.device||'Device'} · {d.details?.site_id||'—'}</small></div><time>{new Date(d.created_at).toLocaleString()}</time></article>{/each}</div>{/if}
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:#818cf8;font-weight:700;margin-bottom:7px}.deploy-action{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:15px;background:#101727;border:1px solid #253149;border-radius:11px;margin-bottom:18px}.deploy-action>div:first-child{display:grid;gap:4px}.deploy-action strong{font-size:11px}.deploy-action small{font-size:9px;color:#64748b}.action-controls{display:flex;gap:7px;min-width:360px}.action-controls select{min-width:0;flex:1}.history{border:1px solid #253149;border-radius:11px;overflow:hidden;background:#101727}.history-row{display:flex;align-items:center;gap:11px;padding:12px;border-bottom:1px solid #1e293b}.history-row:last-child{border:0}.history-icon{width:30px;height:30px;display:grid;place-items:center;border-radius:8px;background:#172136;color:#a5b4fc}.history-copy{display:grid;gap:3px;flex:1}.history-copy strong{font-size:10px}.history-copy small,.history-row time{font-size:9px;color:#64748b}.history-row time{white-space:nowrap}
@media(max-width:700px){.deploy-action{align-items:stretch;flex-direction:column}.action-controls{min-width:0}.history-row{align-items:flex-start}.history-row time{max-width:110px;white-space:normal;text-align:right}}
</style>